const reduced=matchMedia('(prefers-reduced-motion: reduce)'),journey=document.querySelector('.performance-journey'),route=journey.querySelector('#journey-route'),pause=journey.querySelector('.journey-pause');
const travelers=[...journey.querySelectorAll('.journey-traffic')].map(el=>({el,speed:Number(el.dataset.speed),offset:Number(el.dataset.offset),reverse:el.dataset.reverse==='true'})),chapters=[...journey.querySelectorAll('.journey-chapter')];
const routeLength=route.getTotalLength(),mobile=matchMedia('(max-width:600px)');
for(let i=0;i<2;i++){const img=document.createElement('img');img.src=i?'assets/road-truck-top.webp':'assets/road-car-top.webp';img.alt='';img.className='mobile-traffic'+(i?' mobile-truck':'');img.hidden=!mobile.matches;journey.querySelector('.journey-road').append(img);}
const mobileCars=[...journey.querySelectorAll('.mobile-traffic')];
let visible=false,paused=false,frame=0,last=0,elapsed=0,gearVisible=false,gearRender=null,gearLoading=false,gearFailed=false,pointer={x:0,y:0};
const gear=document.querySelector('.gear-live'),canvas=document.querySelector('#live-gear-canvas');
const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
function traffic(scrollTravel=0){for(const [i,t] of travelers.entries()){const position=(t.offset*routeLength+elapsed*t.speed+scrollTravel)%routeLength,distance=t.reverse?routeLength-position:position,lane=t.reverse?-19:19,p=route.getPointAtLength(distance),q=route.getPointAtLength(Math.min(routeLength,distance+1)),angle=Math.atan2(q.y-p.y,q.x-p.x);t.el.setAttribute('transform',`translate(${p.x-Math.sin(angle)*lane} ${p.y+Math.cos(angle)*lane}) rotate(${angle*180/Math.PI+(t.reverse?270:90)})`);}mobileCars.forEach((el,i)=>{el.hidden=!mobile.matches;el.style.transform=`translateY(${640+((elapsed*(i?60:80)+scrollTravel+i*1000)%Math.max(1,journey.offsetHeight-690))}px)`;});}
function paint(time){const r=journey.getBoundingClientRect();if(visible){const scrollTravel=Math.max(0,-r.top)*.5;traffic(reduced.matches?0:scrollTravel);if(!reduced.matches){journey.style.setProperty('--factory-lift',`${clamp(-r.top/740,-.3,1)*-22}px`);journey.style.setProperty('--origin-lift',`${clamp(-r.top/740,-.3,1)*-40}px`);for(const chapter of chapters){const box=chapter.getBoundingClientRect(),p=clamp((innerHeight*.5-(box.top+box.height*.5))/innerHeight,-.6,.6);chapter.style.setProperty('--copy-y',`${p*-20}px`);chapter.style.setProperty('--art-y',`${p*-52}px`);chapter.style.setProperty('--art-x',`${p*10}px`);chapter.style.setProperty('--vehicle-x',`${p*-62}px`);}}}if(gearVisible&&gearRender){const b=gear.getBoundingClientRect();gearRender(time,clamp(1-b.top/innerHeight,.6,.95),pointer,paused||reduced.matches);}}
function running(){return !document.hidden&&!paused&&!reduced.matches&&(visible||gearVisible&&gearRender);}
function tick(time){frame=0;if(!running())return;elapsed+=(last?Math.min(50,time-last):16)/1000;last=time;paint(time);frame=requestAnimationFrame(tick);}
function sync(){last=0;if(running()&&!frame)frame=requestAnimationFrame(tick);else if(!running()&&frame){cancelAnimationFrame(frame);frame=0;}pause.setAttribute('aria-pressed',String(paused));pause.setAttribute('aria-label',paused?'Play road animation':'Pause road animation');pause.innerHTML=paused?'▷ <span>Play motion</span>':'Ⅱ <span>Pause motion</span>';if(reduced.matches)paint(performance.now());}
pause.addEventListener('click',()=>{paused=!paused;sync()});new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;sync()},{threshold:0}).observe(journey);
async function loadGear(){if(gearLoading||gearRender||gearFailed)return;gearLoading=true;try{const {mountGearScene}=await import('./gear-scene.js');gearRender=await mountGearScene(canvas,reduced.matches);gearRender(performance.now(),.8,{x:0,y:0},true);gear.classList.add('gear-ready');sync();}catch(error){gearFailed=true;canvas.hidden=true;gear.dataset.render='fallback';console.warn('Gear scene using image fallback:',error.message);}finally{gearLoading=false;}}
new IntersectionObserver(entries=>{gearVisible=entries[0].isIntersecting;if(gearVisible)loadGear();sync()},{threshold:.1,rootMargin:'60px'}).observe(gear);
gear.addEventListener('pointermove',e=>{if(reduced.matches)return;const r=gear.getBoundingClientRect();pointer={x:(e.clientX-r.left)/r.width-.5,y:(e.clientY-r.top)/r.height-.5};});gear.addEventListener('pointerleave',()=>pointer={x:0,y:0});
document.addEventListener('visibilitychange',sync);reduced.addEventListener('change',sync);mobile.addEventListener('change',()=>{traffic();sync()});
journey.querySelectorAll('[data-journey-filter]').forEach(button=>button.addEventListener('click',()=>window.openCatalog(button.dataset.journeyFilter)));
traffic();
